import React, {useEffect, useState} from "react";
import {Alert, Button, Checkbox, Chip, Dialog, DialogActions, DialogContent, DialogTitle, FormControlLabel, MenuItem, Pagination, TextField} from "@mui/material";
import {Link, useSearchParams} from "react-router-dom";
import QueryError from "../shared/QueryError";
import {PolicyView, PricingAccess, PricingFilter, PricingPolicyData, PurchaseSnapshot, previewMarkup, pricingStatuses, useBulkReceiptMarkupMutation, useLazyExportReceiptPricingQuery, useReceiptPriceHistoryQuery, useReceiptPricingActionMutation, useReceiptPricingAuditQuery, useReceiptPricingPolicyQuery, useReceiptPricingQuery, useReceiptPricingRowQuery, useReceiptPricingStagesQuery, useSaveReceiptPricingPolicyMutation} from "./receiptPricingApi";
import useDebounce from "../../hooks/useDebounce";
import "./costing.css";

const message = (error: unknown) => {const value = error as {data?: {message?: string}; message?: string}; return value?.data?.message || value?.message || "Не удалось сохранить. Обновите данные и повторите действие.";};
const money = (value: number | null | undefined) => value == null ? "—" : value.toLocaleString("ru-RU", {minimumFractionDigits: 2, maximumFractionDigits: 8});
const dateTime = (date: string | null) => date ? new Date(date).toLocaleString("ru-RU") : "—";
const canView = (a: PricingAccess) => a.canEditCost || a.canSetMarkup || a.canApprove || a.canOverridePurchase || a.canManagePolicy || a.canManagePurchases;
const eventNames: Record<string, string> = {receipt_posted: "Приход проведён", revision_created: "Новая версия", cost_saved: "Себестоимость сохранена", cost_confirmed: "Себестоимость подтверждена", markup_set: "Наценка изменена", purchase_corrected: "Источник закупки уточнён", price_submitted: "Отправлено на утверждение", price_approved: "Цена утверждена", price_rejected: "Цена отклонена"};

function PolicyEditor({view, close}: {view: PolicyView; close: () => void}) {
    const [data, setData] = useState<PricingPolicyData>(view.policy.data); const [failure, setFailure] = useState(""); const [save, state] = useSaveReceiptPricingPolicyMutation();
    const {data: audit} = useReceiptPricingAuditQuery();
    const update = (key: keyof PricingPolicyData, value: unknown) => setData(d => ({...d, [key]: value}));
    const grant = (userId: number, flag: number, on: boolean) => setData(d => {const permissions = d.grants.find(g => g.userId === userId)?.permissions || 0; return {...d, grants: [...d.grants.filter(g => g.userId !== userId), {userId, permissions: on ? permissions | flag : permissions & ~flag}]};});
    return <Dialog open onClose={close} maxWidth="md" fullWidth><DialogTitle>Политика цен и права сотрудников</DialogTitle><DialogContent>
        <Alert severity="info" sx={{mb: 2}}>Администратор назначает права отдельно. Для ввода себестоимости назначьте экономиста; для публикации — утверждающего.</Alert>
        {failure && <Alert severity="error">{failure}</Alert>}
        <div className="cost-fields">{([["minimumMarkup", "Минимальная наценка, %"], ["maximumMarkup", "Максимальная наценка, %"], ["roundingStep", "Шаг округления, BYN"], ["significantChangePercent", "Предупреждать об изменении от, %"]] as const).map(([key, label]) => <TextField key={key} type="number" label={label} value={data[key]} onChange={e => update(key, Number(e.target.value))} inputProps={{step: "any"}}/>)}<TextField label="Прайс-листы через запятую" value={data.priceLists.join(", ")} onChange={e => update("priceLists", e.target.value.split(",").map(s => s.trim()))}/></div>
        <FormControlLabel control={<Checkbox checked={data.allowNegativeMarkup} onChange={(_, checked) => update("allowNegativeMarkup", checked)}/>} label="Разрешить отрицательную наценку в пределах политики"/>
        <div className="cost-table-wrap"><table className="cost-table"><thead><tr><th>Сотрудник</th>{["Экономист", "Наценка", "Утверждение", "Источник закупки", "Закупки и оплаты"].map(x => <th key={x}>{x}</th>)}</tr></thead><tbody>{view.users.map(u => <tr key={u.id}><td>{u.name} <small>#{u.id}</small></td>{[1, 2, 4, 8, 16].map((flag, i) => <td key={flag}><Checkbox inputProps={{"aria-label": `${u.name}: ${["экономист", "наценка", "утверждение", "источник", "закупки и оплаты"][i]}`}} checked={Boolean((data.grants.find(g => g.userId === u.id)?.permissions || 0) & flag)} onChange={(_, checked) => grant(u.id, flag, checked)}/></td>)}</tr>)}</tbody></table></div>
        <details><summary>Аудит прав и отклонённых попыток</summary>{audit?.map(a => <p key={a.id}>{dateTime(a.at)} · {a.actor} · {a.action}<small className="cost-note">{a.note}</small></p>)}</details>
    </DialogContent><DialogActions><Button onClick={close}>Закрыть</Button><Button variant="contained" disabled={state.isLoading} onClick={async () => {try {await save({stamp: view.policy.stamp, data}).unwrap(); close();} catch (e) {setFailure(message(e));}}}>Сохранить политику</Button></DialogActions></Dialog>;
}

function PurchaseEditor({purchase, save, close}: {purchase: PurchaseSnapshot; save: (p: PurchaseSnapshot, reason: string) => Promise<void>; close: () => void}) {
    const [p, setP] = useState(purchase); const [reason, setReason] = useState(""); const [failure, setFailure] = useState(""); const [busy, setBusy] = useState(false);
    const update = (key: keyof PurchaseSnapshot, value: unknown) => setP(prev => ({...prev, [key]: value}));
    return <Dialog open onClose={close} maxWidth="sm" fullWidth><DialogTitle>Уточнить источник закупки</DialogTitle><DialogContent>
        <Alert severity="info" sx={{mb: 2}}>Изменение сохраняется с основанием и сбрасывает подтверждение экономиста. Единица и коэффициент прихода зафиксированы складом.</Alert>{failure && <Alert severity="error">{failure}</Alert>}
        <div className="cost-fields"><TextField label="Цена за закупочную единицу" type="number" value={p.originalUnitPrice ?? ""} disabled={p.confirmedDocument} onChange={e => update("originalUnitPrice", e.target.value === "" ? null : Number(e.target.value))}/><TextField label="Закупочная единица" value={p.purchaseUnit} onChange={e => update("purchaseUnit", e.target.value)}/><TextField label="Валюта закупки" value={p.currency} onChange={e => update("currency", e.target.value.toUpperCase())}/><TextField type="number" label="Курс BYN за 1 единицу валюты" value={p.fxRate ?? ""} onChange={e => update("fxRate", e.target.value === "" ? null : Number(e.target.value))}/><TextField type="date" label="Дата курса" InputLabelProps={{shrink: true}} value={p.fxDate ?? ""} onChange={e => update("fxDate", e.target.value)}/><TextField label="Источник курса" value={p.fxSource} onChange={e => update("fxSource", e.target.value)}/><TextField type="number" label="Входной НДС, %" value={p.vatPercent ?? ""} onChange={e => update("vatPercent", e.target.value === "" ? null : Number(e.target.value))}/><TextField type="number" label="Возмещаемая доля НДС, %" value={p.recoverableVatPercent} onChange={e => update("recoverableVatPercent", Number(e.target.value))}/></div>
        <FormControlLabel control={<Checkbox checked={!p.confirmedDocument} onChange={(_, checked) => update("confirmedDocument", !checked)}/>} label="Ручной источник с обязательным основанием"/><FormControlLabel control={<Checkbox checked={p.priceIncludesVat} onChange={(_, checked) => update("priceIncludesVat", checked)}/>} label="Закупочная цена включает НДС"/>
        <TextField fullWidth required multiline label="Основание уточнения / ручного источника" value={reason} onChange={e => setReason(e.target.value)}/>
    </DialogContent><DialogActions><Button onClick={close}>Отмена</Button><Button disabled={!reason.trim() || busy} onClick={async () => {setBusy(true); try {await save(p, reason); close();} catch (e) {setFailure(message(e));} finally {setBusy(false);}}}>Сохранить источник</Button></DialogActions></Dialog>;
}

function PricingEditor({id, access, policy, close}: {id: string; access: PricingAccess; policy: PricingPolicyData; close: () => void}) {
    const {data, error, isError, refetch} = useReceiptPricingRowQuery(id); const [act, actionState] = useReceiptPricingActionMutation();
    const [cost, setCost] = useState(""); const [note, setNote] = useState(""); const [markup, setMarkup] = useState(""); const [vat, setVat] = useState("0");
    const [effective, setEffective] = useState(""); const [priceList, setPriceList] = useState("default"); const [reason, setReason] = useState(""); const [failure, setFailure] = useState(""); const [purchaseOpen, setPurchaseOpen] = useState(false);
    const c = data?.calculation; const {data: history} = useReceiptPriceHistoryQuery({productId: c?.productId || 0, priceList}, {skip: !c});
    useEffect(() => {if (c) {setCost(c.costByn?.toString() ?? ""); setNote(c.calculationNote); setMarkup(c.markupPercent?.toString() ?? ""); setVat(c.salesVatPercent.toString());}}, [c]);
    if (isError) return <Dialog open onClose={close}><DialogContent><QueryError error={error} onRetry={refetch}/></DialogContent></Dialog>;
    if (!c || !data) return <Dialog open onClose={close}><DialogContent>Загрузка расчёта…</DialogContent></Dialog>;
    const readonly = c.status === 4 || c.status === 5; const costDirty = cost !== (c.costByn?.toString() ?? "") || note !== c.calculationNote;
    const markupDirty = markup !== (c.markupPercent?.toString() ?? "") || vat !== c.salesVatPercent.toString();
    const preview = costDirty || markupDirty ? previewMarkup(cost, markup, String(policy.roundingStep)) : c.proposedPriceExVat == null ? null : String(c.proposedPriceExVat); const busy = actionState.isLoading;
    const action = async (name: Parameters<typeof act>[0]["action"]) => {setFailure(""); try {await act({id, stamp: c.stamp, action: name, ...(name === "cost" ? {cost: cost.replace(",", "."), note} : {}), ...(name === "markup" ? {markup: markup.replace(",", "."), vatPercent: vat.replace(",", ".")} : {}), ...(name === "reject" ? {reason} : {}), ...(name === "approve" ? {effectiveFrom: effective ? new Date(effective).toISOString() : null, priceList} : {})}).unwrap(); if (name === "approve" || name === "revise") close();} catch (e) {setFailure(message(e));}};
    return <Dialog open onClose={close} maxWidth="lg" fullWidth><DialogTitle>{c.productName} · версия {c.version}<Chip sx={{ml: 2}} size="small" label={pricingStatuses[c.status]}/></DialogTitle><DialogContent>
        {failure && <Alert severity="error" action={<Button onClick={refetch}>Обновить</Button>}>{failure}</Alert>}{data.warnings.map(w => <Alert key={w} severity="warning" sx={{mb: 1}}>{w}</Alert>)}
        {c.purchaseId && <Alert severity={c.managementEvidence?.cost.isPreliminary ? "warning" : "info"} sx={{mb: 2}}>Управленческая закупка: {c.managementEvidence ? `версия ${c.managementEvidence.version} · ${c.managementEvidence.cost.method}` : "выберите версию стоимости партии"}. <Button component={Link} to={`/costing?purchaseId=${c.purchaseId}`}>Оплаты и стоимость партии</Button></Alert>}<div className="cost-stats" style={{marginBottom: 22}}><div className="cost-stat"><span>1. Закупочная цена · только чтение</span><strong>{money(c.purchase.originalUnitPrice)} {c.purchase.currency}</strong><small>за {c.purchase.purchaseUnit}; {money(c.purchase.bynPerBaseUnit)} BYN/{c.purchase.baseUnit}</small><small>{c.purchase.priceIncludesVat ? "С НДС" : "Без НДС"} · {c.purchase.vatPercent ?? "?"}%</small></div><div className="cost-stat"><span>Действующая цена без НДС</span><strong>{money(data.currentPrice?.priceExVat)} BYN</strong><small>{data.currentPrice ? dateTime(data.currentPrice.effectiveFrom) : "Ожидает утверждения"}</small></div><div className="cost-stat"><span>4. Предлагаемая цена без НДС</span><strong data-testid="pricing-preview">{preview ?? "—"} BYN</strong><small>За {c.purchase.baseUnit}. {costDirty || markupDirty ? "Предпросмотр — изменения не сохранены" : "Публикуется после утверждения"}</small></div></div>
        <div className="cost-fields"><TextField label="2. Себестоимость, BYN/базовая единица" value={cost} disabled={!access.canEditCost || readonly || !!c.purchaseId} onChange={e => setCost(e.target.value)} inputProps={{inputMode: "decimal"}} helperText="Без возмещаемого входного НДС"/><TextField label="3. Наценка от себестоимости, %" value={markup} disabled={!access.canSetMarkup || readonly || !c.confirmedAt} onChange={e => setMarkup(e.target.value)} inputProps={{inputMode: "decimal"}}/><TextField label="НДС продажи, %" value={vat} disabled={!access.canSetMarkup || readonly || !c.confirmedAt} onChange={e => setVat(e.target.value)} inputProps={{inputMode: "decimal"}}/></div>
        <TextField sx={{my: 2}} fullWidth multiline label="Обоснование себестоимости" value={note} disabled={!access.canEditCost || readonly} onChange={e => setNote(e.target.value)}/>
        <div className="cost-actions">{access.canEditCost && !readonly && <>{!c.purchaseId && <Button disabled={busy || !cost.trim()} onClick={() => action("cost")}>Сохранить себестоимость</Button>}<Button disabled={busy || c.status !== 1 || costDirty || (!!c.purchaseId && (!c.managementEvidence || c.managementEvidence.cost.isPreliminary))} onClick={() => action("confirm")}>Подтвердить себестоимость</Button></>}{access.canSetMarkup && !readonly && <><Button disabled={busy || !c.confirmedAt || costDirty || markup === ""} onClick={() => action("markup")}>Сохранить наценку</Button><Button disabled={busy || c.status !== 3 || costDirty || markupDirty} onClick={() => action("submit")}>Отправить на утверждение</Button></>}{access.canOverridePurchase && !readonly && !c.purchaseId && <Button onClick={() => setPurchaseOpen(true)}>Уточнить источник закупки</Button>}{access.canEditCost && c.status === 5 && <Button disabled={busy} onClick={() => action("revise")}>Создать новую версию</Button>}</div>
        {c.confirmedAt && <p className="cost-note">Подтвердил: {c.economist} · {dateTime(c.confirmedAt)}</p>}
        {c.status === 4 && access.canApprove && <section className="cost-line"><h3>Решение по цене</h3><div className="cost-fields"><TextField type="datetime-local" label="Начало действия (пусто — сейчас)" InputLabelProps={{shrink: true}} value={effective} onChange={e => setEffective(e.target.value)}/><TextField select label="Прайс-лист" value={priceList} onChange={e => setPriceList(e.target.value)}>{policy.priceLists.map(p => <MenuItem key={p} value={p}>{p}</MenuItem>)}</TextField></div><Alert sx={{my: 2}} severity="info">После утверждения цена будет опубликована с указанного времени. Предыдущая цена сохранится в истории.</Alert><Button variant="contained" disabled={busy} onClick={() => action("approve")}>Утвердить цену</Button><TextField sx={{mt: 2}} fullWidth label="Причина отклонения" value={reason} onChange={e => setReason(e.target.value)}/><Button disabled={busy || !reason.trim()} onClick={() => action("reject")}>Отклонить с причиной</Button></section>}
        <details style={{marginTop: 20}}><summary>Реквизиты поступления и источник</summary><p>{c.supplier || "Поставщик не указан"} · {c.warehouse} · {dateTime(c.postedAt)}</p><p>Документ: {c.purchase.sourceDocumentNumber || "Нет источника"} · GTIN {c.gtin || "—"}</p><p>Принято: {c.acceptedQuantity} {c.purchase.baseUnit}; 1 {c.purchase.purchaseUnit} = {c.purchase.unitsPerPurchaseUnit} {c.purchase.baseUnit}</p><p>Курс {c.purchase.fxRate ?? "—"}; {c.purchase.fxDate || "—"}; {c.purchase.fxSource || "не указан"}. Возмещаемый НДС: {c.purchase.recoverableVatPercent}%.</p><p>Закупка без возмещаемого НДС: {money(c.purchase.bynExRecoverableVatPerBaseUnit)} BYN/{c.purchase.baseUnit}. Приход #{c.receiptId}</p></details>
        <details><summary>История отпускных цен</summary>{history?.length ? history.map(p => <p key={p.id}>{money(p.priceExVat)} BYN без НДС / {money(p.priceIncVat)} с НДС · {p.baseUnit}<br/>{dateTime(p.effectiveFrom)} — {p.effectiveTo ? dateTime(p.effectiveTo) : "без окончания"} · {p.approvedBy}<br/><small>{p.publishedAt ? "Опубликована" : "Ожидает даты действия / публикации"}</small></p>) : <p>Утверждённых цен пока нет.</p>}</details>
        <details><summary>Журнал расчёта</summary>{c.events.map((e, i) => <p key={i}>{dateTime(e.at)} · {e.actor} · {eventNames[e.action] || e.action}<br/><small className="cost-note">{e.note}</small></p>)}</details>
        {purchaseOpen && <PurchaseEditor purchase={c.purchase} close={() => setPurchaseOpen(false)} save={async (purchase, reason) => {await act({id, stamp: c.stamp, action: "purchase", purchase, reason}).unwrap();}}/>}
    </DialogContent><DialogActions><Button onClick={close}>Закрыть</Button></DialogActions></Dialog>;
}

function Registry({view}: {view: PolicyView}) {
    const [params] = useSearchParams(); const [query, setQuery] = useState(""); const search = useDebounce(query); const [filters, setFilters] = useState<PricingFilter>({page: 1, ...(params.get("productId") ? {productId: Number(params.get("productId"))} : {})});
    const fullView = canView(view.access); const filter = {...filters, search};
    const {data, isError, error, isLoading, refetch} = useReceiptPricingQuery(filter, {skip: !fullView, pollingInterval: 10000});
    const stages = useReceiptPricingStagesQuery(filter, {skip: fullView, pollingInterval: 10000});
    const [selected, setSelected] = useState<string[]>([]); const [editId, setEditId] = useState<string | null>(null); const [policyOpen, setPolicyOpen] = useState(false);
    const [bulkMarkup, setBulkMarkup] = useState(""); const [bulkVat, setBulkVat] = useState("0"); const [failure, setFailure] = useState(""); const [bulk, bulkState] = useBulkReceiptMarkupMutation(); const [exportFile] = useLazyExportReceiptPricingQuery();
    const update = (key: keyof PricingFilter, value: unknown) => {setFilters(f => ({...f, [key]: value === "" ? undefined : value, page: 1})); setSelected([]);};
    const download = async () => {try {const blob = await exportFile(filter).unwrap(); const url = URL.createObjectURL(blob); const a = document.createElement("a"); a.href = url; a.download = "receipt-pricing.xlsx"; a.click(); URL.revokeObjectURL(url);} catch (e) {setFailure(message(e));}};
    return <><header className="cost-header"><div><span className="cost-eyebrow">Поступление → расчёт → утверждение цены</span><h1>Себестоимость и ценообразование</h1><p>Закупка фиксируется при приходе. Экономист подтверждает себестоимость, ответственный задаёт наценку, утверждающий публикует цену.</p></div><div className="cost-actions">{fullView && <Button onClick={download}>Экспорт Excel</Button>}{view.access.canManagePolicy && <Button onClick={() => setPolicyOpen(true)}>Права и политика цен</Button>}</div></header>
        {failure && <Alert severity="error">{failure}</Alert>}{!fullView && <Alert severity="info">Доступны этапы расчётов. Права экономиста, наценки и утверждения назначает администратор.</Alert>}
        <section className="cost-panel"><div className="cost-fields"><TextField size="small" label="Поиск по названию / GTIN" value={query} onChange={e => {setQuery(e.target.value); update("page", 1);}}/><TextField size="small" label="Поставщик" value={filters.supplier || ""} onChange={e => update("supplier", e.target.value)}/><TextField size="small" label="Склад" value={filters.warehouse || ""} onChange={e => update("warehouse", e.target.value)}/><TextField size="small" label="Номер документа поступления" value={filters.document || ""} onChange={e => update("document", e.target.value)}/><TextField size="small" label="SKU / ID товара" type="number" value={filters.productId || ""} onChange={e => update("productId", e.target.value === "" ? undefined : Number(e.target.value))}/><TextField size="small" label="ID поступления" value={filters.receiptId || ""} onChange={e => update("receiptId", e.target.value)}/><TextField size="small" type="date" label="Приход с" InputLabelProps={{shrink: true}} onChange={e => update("from", e.target.value ? new Date(`${e.target.value}T00:00:00`).toISOString() : undefined)}/><TextField size="small" type="date" label="Приход до (не включая)" InputLabelProps={{shrink: true}} onChange={e => update("to", e.target.value ? new Date(`${e.target.value}T00:00:00`).toISOString() : undefined)}/><TextField size="small" select label="Статус" value={filters.status ?? ""} onChange={e => update("status", e.target.value === "" ? undefined : Number(e.target.value))}><MenuItem value="">Все статусы</MenuItem>{pricingStatuses.map((s, i) => <MenuItem value={i} key={s}>{s}</MenuItem>)}</TextField><TextField size="small" select label="Сортировка" value={filters.sort || "date"} onChange={e => update("sort", e.target.value)}>{[["date", "По дате прихода"], ["name", "По названию"], ["cost", "По себестоимости"], ["price", "По отпускной цене"]].map(([value, label]) => <MenuItem key={value} value={value}>{label}</MenuItem>)}</TextField><FormControlLabel control={<Checkbox checked={filters.descending !== false} onChange={(_, checked) => setFilters(f => ({...f, descending: checked, page: 1}))}/>} label="По убыванию"/></div>
        {view.access.canSetMarkup && <div className="cost-actions" style={{marginTop: 20}}><TextField size="small" label="Массовая наценка, %" value={bulkMarkup} onChange={e => setBulkMarkup(e.target.value)}/><TextField size="small" label="НДС для выбранных, %" value={bulkVat} onChange={e => setBulkVat(e.target.value)}/><Button disabled={!selected.length || !bulkMarkup.trim() || bulkState.isLoading} onClick={async () => {try {await bulk({rows: (data?.items || []).filter(r => selected.includes(r.calculation.id)).map(r => ({id: r.calculation.id, stamp: r.calculation.stamp})), markup: bulkMarkup.replace(",", "."), vatPercent: bulkVat.replace(",", ".")}).unwrap(); setSelected([]);} catch (e) {setFailure(message(e));}}}>Применить к выбранным ({selected.length})</Button></div>}
        {(fullView ? isLoading : stages.isLoading) ? <p>Загрузка поступлений…</p> : (fullView ? isError : stages.isError) ? <QueryError error={fullView ? error : stages.error} onRetry={fullView ? refetch : stages.refetch}/> : <div className="cost-table-wrap" style={{marginTop: 20}}><table className="cost-table receipt-pricing-table"><thead><tr>{fullView && <th aria-label="Выбор"/>}<th>Товар / поступление</th>{fullView && <><th className="pricing-core">1. Закупочная цена</th><th className="pricing-core pricing-editable">2. Себестоимость</th><th className="pricing-core pricing-editable">3. Наценка, %</th><th className="pricing-core">4. Отпускная цена</th></>}<th>Статус</th></tr></thead><tbody>{fullView ? data?.items.map(row => {const c = row.calculation; const p = c.purchase; return <tr key={c.id}><td><Checkbox inputProps={{"aria-label": `Выбрать ${c.productName}`}} disabled={!view.access.canSetMarkup || ![2, 3, 6].includes(c.status) || !c.confirmedAt} checked={selected.includes(c.id)} onChange={(_, checked) => setSelected(prev => checked ? [...prev, c.id] : prev.filter(id => id !== c.id))}/></td><td><Button onClick={() => setEditId(c.id)}>{c.productName}</Button><small>{c.gtin || `SKU #${c.productId}`} · {c.acceptedQuantity} {p.baseUnit}</small><small>{p.sourceDocumentNumber || c.receiptId.slice(0, 8)} · {c.supplier} · {dateTime(c.postedAt)}</small></td><td>{p.hasSource ? <>{money(p.originalUnitPrice)} {p.currency}/{p.purchaseUnit}<small>{money(p.bynPerBaseUnit)} BYN/{p.baseUnit} · {p.priceIncludesVat ? "с НДС" : "без НДС"}</small><small>Курс {p.fxRate ?? "—"} · {p.fxDate || "—"}</small></> : <Chip size="small" color="warning" label="Нет источника"/>}</td><td className="pricing-editable">{money(c.costByn)}<small>BYN/{p.baseUnit}</small></td><td className="pricing-editable">{c.markupPercent ?? "—"}%</td><td><strong>{money(c.proposedPriceExVat)} BYN</strong><small>Без НДС/{p.baseUnit}</small><small>Действующая: {money(row.currentPrice?.priceExVat)}</small>{row.warnings.map(w => <small className="pricing-warning" key={w}>{w}</small>)}</td><td><Chip size="small" label={pricingStatuses[c.status]} color={c.status === 5 ? "success" : "default"}/><small>Версия {c.version}</small><Button size="small" onClick={() => setEditId(c.id)}>Открыть</Button></td></tr>;}) : stages.data?.items.map(s => <tr key={s.id}><td>{s.productName}<small>{s.gtin} · {dateTime(s.postedAt)}</small></td><td><Chip size="small" label={pricingStatuses[s.status]}/><small>Версия {s.version}</small></td></tr>)}</tbody></table>{!(fullView ? data?.items.length : stages.data?.items.length) && <div className="cost-empty"><strong>Поступлений для расчёта пока нет</strong><span>Строки появляются автоматически после подтверждённого складского прихода.</span></div>}</div>}
        <Pagination sx={{mt: 2}} page={filters.page || 1} count={Math.ceil(((fullView ? data?.total : stages.data?.total) || 0) / 30)} onChange={(_, page) => {setFilters(f => ({...f, page})); setSelected([]);}}/>
        </section>{editId && <PricingEditor id={editId} access={view.access} policy={view.policy.data} close={() => setEditId(null)}/>} {policyOpen && <PolicyEditor view={view} close={() => setPolicyOpen(false)}/>}</>;
}
export default function ReceiptPricingPage() {
    const {data, isLoading, isError, error, refetch} = useReceiptPricingPolicyQuery();
    return <div className="cost-page">{isLoading ? <p>Загрузка прав…</p> : isError ? <QueryError error={error} onRetry={refetch}/> : data && <Registry view={data}/>}</div>;
}
export function ReceiptPricingProductStage({productId}: {productId: number}) {
    const {data, isError} = useReceiptPricingStagesQuery({productId}, {pollingInterval: 10000}); const stage = data?.items[0];
    return <section className="cost-panel cost-card"><h2>Себестоимость и ценообразование</h2>{isError ? <p>Не удалось загрузить этап расчёта.</p> : <><Chip label={stage ? pricingStatuses[stage.status] : "Расчёт по приходу ещё не создан"} color={stage?.status === 5 ? "success" : "default"}/><p className="cost-note">Последний расчёт{stage ? ` · версия ${stage.version} · ${dateTime(stage.postedAt)}` : " ещё не создан"}</p><Button component={Link} to={`/costing?mode=receipts&productId=${productId}`}>Открыть расчёты по поступлениям</Button></>}</section>;
}
